    public class RJIT_CR_M_00005 : MediatorTestBase
    {
        [TestMethod]
        public void Response_Type_Has_To_Be_A_Record_Type()
        {
            var responseTypeIsNotARecord = (from handler in MediatorImplementations
                                              where handler.Response is not null &&
                                                    handler.Response.GetType() != typeof(Record)
                                              select new
                                              {
                                                  Error = $@"
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
Fullname: {handler.Response.FullQualifiedName}
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
Response: {handler.Response.SyntaxTree}
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
Sample:   {handler.Response.SyntaxTree.Replace(" class ", " record ")}       
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
"
                                              }).ToImmutableList();


            Assert.IsTrue(responseTypeIsNotARecord.IsEmpty(),
                @$"
Documentation: {DocumentationDomain}#RJIT_CR_MR_00005

Please use record types for your response types. To go sure that nothing can manipulate the procesed response
data.

Found:{responseTypeIsNotARecord.Count}

{responseTypeIsNotARecord.Select(e => e.Error).Flatten(Environment.NewLine)}");
        }
    }
